import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link } from "react-router-dom";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { deleteProduct, fetchProducts } from "../../redux/product/productSlice";

const ProductList = () => {
  const dispatch = useDispatch();
  const { products, loading, error } = useSelector((state) => state.product);

  useEffect(() => {
    dispatch(fetchProducts());
  }, [dispatch]);

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this product?")) {
      dispatch(deleteProduct(id));
    }
  };

  const actionBodyTemplate = (rowData) => (
    <div className="d-flex gap-2">
      <Link
        to={`/products/edit/${rowData.id}`}
        className="btn btn-sm btn-warning"
      >
        Edit
      </Link>
      <button
        onClick={() => handleDelete(rowData.id)}
        className="btn btn-sm btn-danger"
      >
        Delete
      </button>
    </div>
  );

  const status = loading ? "loading" : error ? "failed" : "succeeded";

  return (
    <div className="card p-3 mt-4">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h3 className="m-0">Product List</h3>
        <Link to="/products/add" className="btn btn-primary">
          Add Product
        </Link>
      </div>

      {status === "loading" && <div>Loading...</div>}
      {status === "failed" && (
        <div className="text-danger">Error: {JSON.stringify(error)}</div>
      )}

      <DataTable
        value={products}
        paginator
        rows={5}
        stripedRows
        responsiveLayout="scroll"
        emptyMessage="No products found."
      >
        <Column field="name" header="Name" sortable />
        <Column field="description" header="Description" sortable />
        <Column field="price" header="Price" sortable />
        <Column field="stockQuantity" header="Stock" sortable />
        <Column body={actionBodyTemplate} header="Actions" />
      </DataTable>
    </div>
  );
};

export default ProductList;
